    'Procura o menor custo anual (investimento anualizado + energia) que ainda atende todas as pressões e velocidades: dimensiona os tubos por programação linear, escolhe a bomba de menor custo de ciclo de vida e a válvula certa para cada zona. Se não melhorar, nada é alterado.',
    'Looks for the lowest annual cost (annualised investment + energy) that still meets every pressure and velocity: sizes the pipes by linear programming, picks the pump with the lowest life-cycle cost and the right valve for each zone. If nothing improves, nothing changes.',
    'Busca el menor costo anual (inversión anualizada + energía) que aún cumple todas las presiones y velocidades: dimensiona las tuberías por programación lineal, elige la bomba de menor costo de ciclo de vida y la válvula correcta para cada zona. Si no mejora, no se cambia nada.',
  ),
