  'fixfail.notFound': ('o item não existe mais', 'the item no longer exists', 'el elemento ya no existe'),
  'fixfail.nothingNear': ('nenhum tubo ou item compatível a menos de {d} m', 'no compatible pipe or item within {d} m', 'ninguna tubería o elemento compatible a menos de {d} m'),
  'fixfail.needsResults': ('calcule o projeto (F5) antes', 'run the design (F5) first', 'calcule el diseño (F5) antes'),
  'fixfail.noSupply': ('não há fonte de água', 'there is no water supply', 'no hay fuente de agua'),
  'fixfail.noDuty': ('a fonte não precisa de bombeamento', 'the supply needs no pumping', 'la fuente no necesita bombeo'),
  'fixfail.noPump': (
    'nenhuma bomba do catálogo atende sozinha a vazão e a pressão; adicione uma bomba maior ao catálogo',
    'no catalogue pump meets the flow and the pressure alone; add a bigger pump to the catalogue',
    'ninguna bomba del catálogo cumple sola el caudal y la presión; añada una bomba mayor al catálogo',
  ),
  'fixfail.alreadyBest': ('{n} já é a melhor opção do catálogo', '{n} already is the best option in the catalogue', '{n} ya es la mejor opción del catálogo'),
  'fixfail.noPipeAtSupply': ('nenhum tubo da linha principal sai da fonte', 'no mainline pipe leaves the supply', 'ninguna tubería de la línea principal sale de la fuente'),
  'fixfail.noChange': ('não havia nada a mudar', 'there was nothing to change', 'no había nada que cambiar'),
  'fixfail.noOption': ('o catálogo não tem uma opção adequada', 'the catalogue has no suitable option', 'el catálogo no tiene una opción adecuada'),
  'adv.no_supply.why': (
    'O cálculo começa numa fonte de água (poço, reservatório, rede pública ou canal) com nível e pressão conhecidos. Sem ela a água não tem de onde vir e nada pode ser calculado.',
    'The design starts at a water supply (well, reservoir, public mains or canal) with a known level and pressure. Without one the water has nowhere to come from and nothing can be calculated.',
    'El cálculo empieza en una fuente de agua (pozo, reservorio, red pública o canal) con nivel y presión conocidos. Sin ella el agua no tiene de dónde venir y no se puede calcular nada.',
  ),
  'adv.no_supply.how': (
    'Use a ferramenta Fonte de água (WS) e clique na ponta da linha principal por onde a água entra. Marque "Calcular pressão necessária" se ainda não souber a pressão disponível: o programa diz quanto é preciso.',
    'Use the Water supply tool (WS) and click the end of the mainline where the water comes in. Tick "Calculate required pressure" if you do not know the available pressure yet: the program tells you how much is needed.',
    'Use la herramienta Fuente de agua (WS) y haga clic en el extremo de la línea principal por donde entra el agua. Marque "Calcular presión necesaria" si aún no conoce la presión disponible: el programa indica cuánta se necesita.',
  ),
  'adv.no_valves.why': (
    'Cada zona (conjunto de laterais que irrigam juntas) precisa de uma válvula de controle que a ligue à linha principal. É na válvula que o programa separa as zonas e calcula a pressão de cada uma.',
    'Each zone (a set of laterals that irrigate together) needs a control valve that links it to the mainline. The valve is where the program separates the zones and works out the pressure of each one.',
    'Cada zona (conjunto de laterales que riegan juntas) necesita una válvula de control que la una a la línea principal. En la válvula el programa separa las zonas y calcula la presión de cada una.',
  ),
  'adv.no_valves.how': (
    'Coloque uma Válvula de controle (V) onde a linha principal encontra o início da zona. O Bloco de laterais (B) desenha laterais, linha de derivação e válvula de uma vez.',
    'Place a Control valve (V) where the mainline meets the start of the zone. The Lateral block tool (B) draws laterals, submain and valve in one go.',
    'Coloque una Válvula de control (V) donde la línea principal se encuentra con el inicio de la zona. El Bloque de laterales (B) dibuja laterales, portalaterales y válvula de una vez.',
  ),
  'adv.no_hydraulics.why': (
    'O desenho ainda não tem tubos, emissores nem válvulas: só há o que calcular depois que a rede de irrigação é desenhada.',
    'The drawing has no pipes, emitters or valves yet: there is only something to calculate once the irrigation network is drawn.',
    'El dibujo todavía no tiene tuberías, emisores ni válvulas: solo hay algo que calcular cuando la red de riego está dibujada.',
  ),
  'adv.no_hydraulics.how': (
    'Comece por um exemplo (Arquivo → Exemplos) ou pelo Tutorial interativo (Ajuda). Num projeto novo: desenhe a área, gere um Bloco de laterais (B), ligue as válvulas com a linha principal e coloque a fonte de água.',
    'Start from an example (File → Examples) or the Interactive tutorial (Help). For a new design: draw the area, generate a Lateral block (B), link the valves with the mainline and place the water supply.',
    'Empiece por un ejemplo (Archivo → Ejemplos) o por el Tutorial interactivo (Ayuda). En un diseño nuevo: dibuje el área, genere un Bloque de laterales (B), una las válvulas con la línea principal y coloque la fuente de agua.',
  ),
  'adv.unconnected.why': (
    'Só estão ligados itens que se tocam exatamente (dentro da tolerância de conexão). Um item fora da rede não recebe água e fica fora do cálculo; geralmente ele foi solto a poucos centímetros do tubo.',
    'Only items that touch exactly (within the connection tolerance) are joined. An item off the network gets no water and is left out of the calculation; usually it was dropped a few centimetres from the pipe.',
    'Solo están unidos los elementos que se tocan exactamente (dentro de la tolerancia de conexión). Un elemento fuera de la red no recibe agua y queda fuera del cálculo; normalmente se soltó a pocos centímetros de la tubería.',
  ),
  'adv.unconnected.how': (
    'Clique em "Mostrar no desenho" e arraste o item até o tubo com o Snap ligado, ou use a correção, que o leva ao tubo ou item compatível mais próximo.',
    'Click "Show on the drawing" and drag the item onto the pipe with Snap on, or use the correction, which moves it to the nearest compatible pipe or item.',
    'Haga clic en "Mostrar en el dibujo" y arrastre el elemento sobre la tubería con el Snap activado, o use la corrección, que lo lleva a la tubería o elemento compatible más cercano.',
  ),
  'adv.zero_length.why': (
    'Um tubo sem comprimento (os dois pontos no mesmo lugar) não conduz água e atrapalha a montagem da rede. Costuma surgir de um clique duplo acidental.',
    'A pipe without length (both points at the same place) carries no water and confuses the network. It usually comes from an accidental double click.',
    'Una tubería sin longitud (los dos puntos en el mismo lugar) no conduce agua y entorpece el armado de la red. Suele surgir de un doble clic accidental.',
  ),
  'adv.zero_length.how': ('Exclua o tubo; nada se perde.', 'Delete the pipe; nothing is lost.', 'Elimine la tubería; no se pierde nada.'),
  'adv.tiny_segment.why': (
    'Dois vértices mais próximos que a tolerância de conexão viram um só nó; o trecho minúsculo entre eles pode ligar coisas que não deviam se tocar.',
    'Two vertices closer than the connection tolerance become a single node; the tiny piece between them may join things that should not touch.',
    'Dos vértices más cerca que la tolerancia de conexión se vuelven un solo nudo; el tramo diminuto entre ellos puede unir cosas que no deberían tocarse.',
  ),
  'adv.tiny_segment.how': (
    'Remova os vértices repetidos (a correção faz isso sem mudar o traçado).',
    'Remove the repeated vertices (the correction does it without changing the layout).',
    'Quite los vértices repetidos (la corrección lo hace sin cambiar el trazado).',
  ),
  'adv.duplicate_item.why': (
    'Dois itens iguais no mesmo ponto (colados duas vezes, por exemplo) dobram a vazão e o custo na lista de materiais.',
    'Two identical items at the same point (pasted twice, for instance) double the flow and the cost in the bill of materials.',
    'Dos elementos iguales en el mismo punto (pegados dos veces, por ejemplo) duplican el caudal y el costo en la lista de materiales.',
  ),
  'adv.duplicate_item.how': ('Mantenha só um deles.', 'Keep only one of them.', 'Deje solo uno de ellos.'),
  'adv.duplicate_zone_name.why': (
    'Relatórios, turnos e programação identificam as zonas pelo nome; nomes repetidos deixam os resultados ambíguos.',
    'Reports, system flows and the schedule identify the zones by name; repeated names make the results ambiguous.',
    'Los informes, los turnos y la programación identifican las zonas por el nombre; los nombres repetidos hacen ambiguos los resultados.',
  ),
  'adv.duplicate_zone_name.how': (
    'Dê um nome diferente a cada zona nas propriedades da válvula, ou deixe a correção numerá-las.',
    'Give each zone a different name in the valve properties, or let the correction number them.',
    'Dé un nombre distinto a cada zona en las propiedades de la válvula, o deje que la corrección las numere.',
  ),
  'adv.pipes_cross.why': (
    'Tubos que se cruzam sem um vértice comum não estão ligados, como na obra, onde um passa por cima do outro. Se deviam se conectar, falta a junção.',
    'Pipes that cross without a shared vertex are not joined, as on site, where one passes over the other. If they should connect, the junction is missing.',
    'Las tuberías que se cruzan sin un vértice común no están unidas, como en obra, donde una pasa por encima de la otra. Si debían conectarse, falta el nudo.',
  ),
  'adv.pipes_cross.how': (
    'Se é uma conexão (tê ou cruzeta), use "Conectar os tubos no cruzamento". Se um só passa sobre o outro, está certo e o aviso pode ser ignorado.',
    'If it is a connection (a tee or a cross), use "Connect the pipes at the crossing". If one only passes over the other, that is right and the warning can be ignored.',
    'Si es una conexión (te o cruz), use "Conectar las tuberías en el cruce". Si una solo pasa sobre la otra, es correcto y el aviso se puede ignorar.',
  ),
  'adv.mainline_dead_end.why': (
    'Uma ponta da linha principal não chega a nenhuma válvula, fonte ou emissor: o tubo termina no vazio. Ele não leva água a lugar nenhum, mas entra no custo.',
    'An end of the mainline reaches no valve, supply or emitter: the pipe ends in the void. It takes water nowhere but adds to the cost.',
    'Un extremo de la línea principal no llega a ninguna válvula, fuente ni emisor: la tubería termina en el vacío. No lleva agua a ninguna parte, pero suma al costo.',
  ),
  'adv.mainline_dead_end.how': (
    'Ligue a ponta à válvula ou à fonte que ela devia alcançar, ou apague o trecho que sobra. Se o projeto ainda não tem fonte, essa ponta costuma ser o lugar dela.',
    'Join the end to the valve or supply it should reach, or delete the leftover piece. If the design has no supply yet, that end is usually where it goes.',
    'Una el extremo a la válvula o a la fuente a la que debía llegar, o borre el tramo sobrante. Si el diseño aún no tiene fuente, ese extremo suele ser su lugar.',
  ),
  'adv.zone_dead_end.why': (
    'Um tubo da zona termina sem lateral nem emissor na ponta. Às vezes é proposital (ponto de lavagem), às vezes é um trecho esquecido.',
    'A zone pipe ends without a lateral or emitter at its end. Sometimes on purpose (a flushing point), sometimes a forgotten piece.',
    'Una tubería de la zona termina sin lateral ni emisor en el extremo. A veces es a propósito (punto de lavado), a veces es un tramo olvidado.',
  ),
  'adv.zone_dead_end.how': (
    'Se ele não serve para nada, encurte ou apague o trecho para economizar tubo.',
    'If it serves no purpose, shorten or delete it to save pipe.',
    'Si no sirve para nada, acórtela o bórrela para ahorrar tubería.',
  ),
  'adv.zone_no_emitters.why': (
    'A válvula não alimenta nenhum emissor: sem vazão não há o que dimensionar, e a zona fica vazia nos resultados.',
    'The valve feeds no emitter: with no flow there is nothing to size, and the zone stays empty in the results.',
    'La válvula no alimenta ningún emisor: sin caudal no hay nada que dimensionar y la zona queda vacía en los resultados.',
  ),
  'adv.zone_no_emitters.how': (
    'Confira se os tubos e laterais da zona tocam a válvula (saída da válvula = início da linha de derivação). Use "Mostrar no desenho" e ligue-os, ou apague a válvula se a zona não existe.',
    'Check that the zone pipes and laterals touch the valve (valve outlet = start of the submain). Use "Show on the drawing" and join them, or delete the valve if the zone does not exist.',
    'Compruebe que las tuberías y laterales de la zona tocan la válvula (salida de la válvula = inicio del portalaterales). Use "Mostrar en el dibujo" y únalos, o borre la válvula si la zona no existe.',
  ),
  'adv.area_no_emitters.why': (
    'Uma área irrigada foi desenhada, mas não tem emissores dentro; ela entra no balanço hídrico sem ser irrigada.',
    'An irrigated area was drawn but has no emitters inside; it enters the water balance without being irrigated.',
    'Se dibujó un área regada pero no tiene emisores dentro; entra en el balance hídrico sin ser regada.',
  ),
  'adv.area_no_emitters.how': (
    'Gere um Bloco de laterais (B) ou uma Grade de aspersores dentro da área, ou apague a área se ela é só referência.',
    'Generate a Lateral block (B) or a Sprinkler grid inside the area, or delete the area if it is only a reference.',
    'Genere un Bloque de laterales (B) o una Malla de aspersores dentro del área, o borre el área si es solo referencia.',
  ),
  'adv.spec_missing.why': (
    'O item aponta para um modelo que não está no catálogo do projeto (apagado, ou vindo de outro arquivo). Sem as curvas do modelo não é possível calcular.',
    'The item points to a model that is not in the project catalogue (deleted, or coming from another file). Without the model curves it cannot be calculated.',
    'El elemento apunta a un modelo que no está en el catálogo del proyecto (borrado o venido de otro archivo). Sin las curvas del modelo no se puede calcular.',
  ),
  'adv.spec_missing.how': (
    'Escolha um modelo nas propriedades do item, ou use a correção, que aplica um modelo do catálogo (nos tubos, o diâmetro passa a ser escolhido pelo cálculo).',
    'Pick a model in the item properties, or use the correction, which applies a catalogue model (for pipes, the design then chooses the diameter).',
    'Elija un modelo en las propiedades del elemento, o use la corrección, que aplica un modelo del catálogo (en las tuberías, el diámetro pasa a elegirlo el cálculo).',
  ),
  'adv.supply_no_head.why': (
    'A fonte está com pressão fixa igual a zero: é como uma caixa d\'água no nível do chão, sem bomba. Quase nunca é o que se quer, e todas as válvulas ficarão sem pressão.',
    'The supply has a fixed pressure of zero: like a tank at ground level with no pump. It is hardly ever what you want, and every valve will lack pressure.',
    'La fuente tiene presión fija igual a cero: como un tanque a nivel del suelo, sin bomba. Casi nunca es lo que se quiere, y todas las válvulas quedarán sin presión.',
  ),
  'adv.supply_no_head.how': (
    'Informe a pressão real da fonte (rede pública, por exemplo 25 m.c.a.) ou marque "Calcular pressão necessária" para o programa dizer quanto é preciso.',
    'Enter the real supply pressure (public mains, e.g. 25 m of head) or tick "Calculate required pressure" so the program tells you how much is needed.',
    'Ingrese la presión real de la fuente (red pública, por ejemplo 25 m.c.a.) o marque "Calcular presión necesaria" para que el programa diga cuánta se necesita.',
  ),
  'adv.looped_mainline.why': (
    'A linha principal forma um anel. O solver de rede calcula anéis corretamente; o dimensionamento por programação linear usa caminhos em árvore e é repetido com as vazões redistribuídas até estabilizar, e a análise final confere as pressões.',
    'The mainline forms a loop. The network solver handles loops correctly; the linear-programming sizing uses tree paths and is repeated with the redistributed flows until it settles, and the final analysis checks the pressures.',
    'La línea principal forma un anillo. El solver de red calcula los anillos correctamente; el dimensionamiento por programación lineal usa caminos en árbol y se repite con los caudales redistribuidos hasta estabilizarse, y el análisis final verifica las presiones.',
  ),
  'adv.looped_mainline.how': (
    'Nada a fazer se o anel é intencional (ele distribui melhor a pressão). Se não é, remova o trecho que fecha o anel.',
    'Nothing to do if the loop is intended (it spreads the pressure better). If it is not, remove the piece that closes the loop.',
    'Nada que hacer si el anillo es intencional (reparte mejor la presión). Si no lo es, quite el tramo que cierra el anillo.',
  ),
  'adv.no_terrain.why': (
    'Sem curvas de nível nem cotas, o terreno é considerado plano. Em áreas com desnível, subidas e descidas mudam muito a pressão nos emissores.',
    'Without contours or spot heights the ground is taken as flat. On sloping land, rises and falls change the emitter pressures a lot.',
    'Sin curvas de nivel ni cotas, el terreno se considera plano. En terrenos con desnivel, las subidas y bajadas cambian mucho la presión en los emisores.',
  ),
  'adv.no_terrain.how': (
    'Baixe a elevação da internet (Projeto → Terreno), importe um GeoTIFF ou DXF com curvas, ou digite algumas cotas. Em terreno plano de verdade, pode ignorar.',
    'Download the elevation from the internet (Design → Terrain), import a GeoTIFF or a DXF with contours, or type a few spot heights. On truly flat ground you can ignore it.',
    'Descargue la elevación de internet (Diseño → Terreno), importe un GeoTIFF o un DXF con curvas, o escriba algunas cotas. En terreno realmente plano puede ignorarlo.',
  ),
  'adv.not_converged.why': (
    'O cálculo hidráulico não chegou a uma solução estável, geralmente por dados extremos: tubo minúsculo com vazão enorme, bomba muito fora da faixa ou valores zerados.',
    'The hydraulic calculation did not reach a stable solution, usually because of extreme data: a tiny pipe with a huge flow, a pump far outside its range, or zero values.',
    'El cálculo hidráulico no llegó a una solución estable, normalmente por datos extremos: tubería diminuta con caudal enorme, bomba muy fuera de rango o valores en cero.',
  ),
  'adv.not_converged.how': (
    'Resolva primeiro os outros erros da lista (principalmente itens desconectados e modelos faltando) e calcule de novo. Procure diâmetros e pressões absurdos nas propriedades.',
    'First solve the other errors in the list (mainly unconnected items and missing models) and run again. Look for absurd diameters and pressures in the properties.',
    'Resuelva primero los otros errores de la lista (sobre todo elementos desconectados y modelos faltantes) y calcule de nuevo. Busque diámetros y presiones absurdos en las propiedades.',
  ),
  'adv.cannot_meet_pressure_window.why': (
    'Os emissores da zona precisam trabalhar numa faixa de pressão (a janela). Mesmo com os maiores tubos permitidos, a perda de carga ou o desnível deixam algum emissor fora dela: a zona é longa ou inclinada demais, ou a pressão pedida está fora da faixa do bocal.',
    'The emitters of the zone must work within a pressure range (the window). Even with the largest pipes allowed, friction loss or the slope leave some emitter outside it: the zone is too long or too steep, or the pressure asked is outside the nozzle range.',
    'Los emisores de la zona deben trabajar en un rango de presión (la ventana). Incluso con las mayores tuberías permitidas, la pérdida de carga o el desnivel dejan algún emisor fuera: la zona es demasiado larga o empinada, o la presión pedida está fuera del rango de la boquilla.',
  ),
  'adv.cannot_meet_pressure_window.how': (
    'Tente, nesta ordem: deixar o cálculo escolher os diâmetros; dividir a zona em duas válvulas; alimentar as laterais pelo meio; usar emissores autocompensantes; habilitar tubos maiores no catálogo.',
    'Try, in this order: let the design choose the diameters; split the zone into two valves; feed the laterals from the middle; use pressure-compensating emitters; enable larger pipes in the catalogue.',
    'Pruebe, en este orden: dejar que el cálculo elija los diámetros; dividir la zona en dos válvulas; alimentar los laterales por el centro; usar emisores autocompensantes; habilitar tuberías mayores en el catálogo.',
  ),
  'adv.outlet_over_pressure.why': (
    'Algum emissor recebe mais pressão do que o bocal suporta, o que é comum em zonas morro abaixo, onde cada metro de descida soma pressão. Isso aumenta a vazão, o tamanho das gotas e o desgaste.',
    'Some emitter gets more pressure than the nozzle stands, which is common in downhill zones, where every metre of fall adds pressure. It raises the flow, the droplet size and the wear.',
    'Algún emisor recibe más presión de la que soporta la boquilla, algo común en zonas cuesta abajo, donde cada metro de bajada suma presión. Eso aumenta el caudal, el tamaño de gota y el desgaste.',
  ),
  'adv.outlet_over_pressure.how': (
    'Divida a zona por faixas de altitude, use emissores autocompensantes ou reguladores de pressão nas laterais, ou reduza a pressão na válvula.',
    'Split the zone by elevation bands, use pressure-compensating emitters or pressure regulators on the laterals, or lower the pressure at the valve.',
    'Divida la zona por franjas de altitud, use emisores autocompensantes o reguladores de presión en los laterales, o reduzca la presión en la válvula.',
  ),
  'adv.velocity_exceeded.why': (
    'A água passa rápido demais neste tubo (acima do limite dos parâmetros, em geral 1,5 a 2 m/s). Velocidade alta gasta pressão, aumenta o golpe de aríete e desgasta o tubo.',
    'Water runs too fast in this pipe (above the limit in the parameters, usually 1.5 to 2 m/s). High velocity wastes pressure, increases water hammer and wears the pipe.',
    'El agua pasa demasiado rápido por esta tubería (por encima del límite de los parámetros, en general 1,5 a 2 m/s). La velocidad alta gasta presión, aumenta el golpe de ariete y desgasta la tubería.',
  ),
  'adv.velocity_exceeded.how': (
    'Deixe o cálculo escolher o diâmetro (se você o fixou) ou use um tubo maior. Se já é o maior do catálogo, divida a vazão: mais turnos ou mais uma linha.',
    'Let the design choose the diameter (if you fixed it) or use a bigger pipe. If it is already the largest in the catalogue, split the flow: more system flows or another line.',
    'Deje que el cálculo elija el diámetro (si usted lo fijó) o use una tubería mayor. Si ya es la mayor del catálogo, divida el caudal: más turnos u otra línea.',
  ),
  'adv.pressure_rating_exceeded.why': (
    'A pressão de trabalho passa da classe (PN) do tubo, que pode estourar. Acontece perto de bombas fortes ou no ponto mais baixo do terreno.',
    'The working pressure exceeds the class (PN) of the pipe, which may burst. It happens near strong pumps or at the lowest point of the ground.',
    'La presión de trabajo supera la clase (PN) de la tubería, que puede reventar. Pasa cerca de bombas fuertes o en el punto más bajo del terreno.',
  ),
  'adv.pressure_rating_exceeded.how': (
    'Use um tubo de classe maior no mesmo diâmetro (a correção escolhe o mais barato que aguenta), ou reduza a pressão: bomba menor ou válvula redutora.',
    'Use a higher-class pipe of the same diameter (the correction picks the cheapest that withstands it), or lower the pressure: a smaller pump or a pressure-reducing valve.',
    'Use una tubería de clase mayor en el mismo diámetro (la corrección elige la más barata que resiste), o reduzca la presión: bomba menor o válvula reductora.',
  ),
  'adv.surge_rating_exceeded.why': (
    'Ao fechar uma válvula rápido, a água em movimento para de repente e gera um pico de pressão (golpe de aríete). Somado à pressão normal, ele passa da classe do tubo.',
    'Closing a valve fast stops the moving water suddenly and causes a pressure spike (water hammer). Added to the normal pressure it exceeds the pipe class.',
    'Al cerrar una válvula rápido, el agua en movimiento se detiene de golpe y genera un pico de presión (golpe de ariete). Sumado a la presión normal, supera la clase de la tubería.',
  ),
  'adv.surge_rating_exceeded.how': (
    'Use tubo de classe maior, feche as válvulas mais devagar (tempo de fechamento nos parâmetros) ou reduza a velocidade com um tubo mais largo.',
    'Use a higher-class pipe, close the valves more slowly (closure time in the parameters) or lower the velocity with a wider pipe.',
    'Use tubería de clase mayor, cierre las válvulas más despacio (tiempo de cierre en los parámetros) o reduzca la velocidad con una tubería más ancha.',
  ),
  'adv.valve_flow_out_of_range.why': (
    'A vazão da zona está fora da faixa da válvula escolhida: pequena demais, ela perde muita pressão; grande demais, não regula bem.',
    'The zone flow is outside the range of the chosen valve: too small a valve loses a lot of pressure; too big a valve does not regulate well.',
    'El caudal de la zona está fuera del rango de la válvula elegida: si es pequeña pierde mucha presión; si es grande no regula bien.',
  ),
  'adv.valve_flow_out_of_range.how': (
    'Troque a válvula por uma do tamanho certo (a correção escolhe a menor que atende).',
    'Change the valve to the right size (the correction picks the smallest that fits).',
    'Cambie la válvula por una del tamaño correcto (la corrección elige la menor que sirve).',
  ),
  'adv.valve_pressure_deficit.why': (
    'A pressão que chega à válvula é menor que a que a zona precisa: a fonte não tem pressão para vencer a perda na linha principal e o desnível até a zona.',
    'The pressure reaching the valve is lower than the zone needs: the supply does not have the pressure to overcome the mainline loss and the rise to the zone.',
    'La presión que llega a la válvula es menor que la que necesita la zona: la fuente no tiene presión para vencer la pérdida en la línea principal y el desnivel hasta la zona.',
  ),
  'adv.valve_pressure_deficit.how': (
    'Coloque ou troque a bomba (a correção escolhe uma para a vazão e a pressão), use tubos maiores na linha principal ou divida os turnos. Se a pressão da fonte foi só um palpite, deixe o programa calculá-la.',
    'Add or change the pump (the correction picks one for the flow and the pressure), use larger mainline pipes or split the system flows. If the supply pressure was only a guess, let the program calculate it.',
    'Coloque o cambie la bomba (la corrección elige una para el caudal y la presión), use tuberías mayores en la línea principal o divida los turnos. Si la presión de la fuente era solo una estimación, deje que el programa la calcule.',
  ),
  'adv.pivot_pressure_deficit.why': (
    'O pivô precisa de uma pressão na entrada para que o último aspersor funcione; a linha principal entrega menos que isso.',
    'The pivot needs an inlet pressure so that the last sprinkler works; the mainline delivers less than that.',
    'El pivote necesita una presión de entrada para que funcione el último aspersor; la línea principal entrega menos.',
  ),
  'adv.pivot_pressure_deficit.how': (
    'Escolha uma bomba adequada, aumente o diâmetro da adutora ou confira a pressão de ponta pedida nas propriedades do pivô.',
    'Choose a suitable pump, increase the diameter of the supply main or check the end pressure asked in the pivot properties.',
    'Elija una bomba adecuada, aumente el diámetro de la aductora o revise la presión de punta pedida en las propiedades del pivote.',
  ),
  'adv.supply_flow_exceeded.why': (
    'O turno pede mais vazão do que a fonte fornece (a vazão de projeto da fonte). Na prática faltaria água e as pressões cairiam.',
    'The system flow asks for more flow than the supply gives (its design flow). In practice the water would run short and the pressures would drop.',
    'El turno pide más caudal del que da la fuente (su caudal de diseño). En la práctica faltaría agua y las presiones bajarían.',
  ),
  'adv.supply_flow_exceeded.how': (
    'Divida as zonas em mais turnos (a correção reagrupa para que nenhum passe da vazão da fonte), ou aumente a vazão da fonte se ela realmente comporta.',
    'Split the zones into more system flows (the correction regroups them so that none exceeds the supply flow), or raise the supply flow if it really allows it.',
    'Divida las zonas en más turnos (la corrección las reagrupa para que ninguno supere el caudal de la fuente), o aumente el caudal de la fuente si realmente lo permite.',
  ),
  'adv.supply_head_exceeded.why': (
    'Para atender todas as válvulas, a fonte precisaria de mais pressão do que o máximo informado para ela.',
    'To serve every valve the supply would need more pressure than the maximum entered for it.',
    'Para atender todas las válvulas, la fuente necesitaría más presión que el máximo indicado para ella.',
  ),
  'adv.supply_head_exceeded.how': (
    'Coloque uma bomba (booster) depois da fonte, use tubos maiores ou divida os turnos para reduzir a perda de carga.',
    'Add a booster pump after the supply, use larger pipes or split the system flows to reduce the friction loss.',
    'Coloque una bomba (booster) después de la fuente, use tuberías mayores o divida los turnos para reducir la pérdida de carga.',
  ),
  'adv.pump_out_of_range.why': (
    'A bomba trabalha fora da faixa de vazão da sua curva: pequena demais, não entrega a vazão; grande demais, trabalha perto do fechamento e desperdiça energia.',
    'The pump works outside the flow range of its curve: too small, it cannot deliver the flow; too big, it runs near shut-off and wastes energy.',
    'La bomba trabaja fuera del rango de caudal de su curva: si es pequeña, no entrega el caudal; si es grande, trabaja cerca del cierre y desperdicia energía.',
  ),
  'adv.pump_out_of_range.how': (
    'Escolha uma bomba adequada: a correção compara as bombas do catálogo e fica com a de menor custo de compra + energia que atende todos os turnos.',
    'Choose a suitable pump: the correction compares the catalogue pumps and keeps the one with the lowest purchase + energy cost that serves every system flow.',
    'Elija una bomba adecuada: la corrección compara las bombas del catálogo y se queda con la de menor costo de compra + energía que atiende todos los turnos.',
  ),
  'adv.pump_suction_lift.why': (
    'Uma bomba de superfície puxa a água por vácuo, e a pressão atmosférica só empurra a água até uns 10 m; na prática, com perdas e o NPSH, o limite é uns 7 m ao nível do mar (menos em altitude). Além disso a bomba cavita ou perde a escorva.',
    'A surface pump pulls the water through a vacuum, and the atmospheric pressure only pushes water up about 10 m; in practice, with losses and the NPSH, the limit is about 7 m at sea level (less at altitude). Beyond it the pump cavitates or loses its prime.',
    'Una bomba de superficie succiona el agua por vacío, y la presión atmosférica solo empuja el agua unos 10 m; en la práctica, con pérdidas y el NPSH, el límite es unos 7 m a nivel del mar (menos en altitud). Más allá la bomba cavita o pierde el cebado.',
  ),
  'adv.pump_suction_lift.how': (
    'Use uma bomba submersa dentro do poço, ou instale a bomba de superfície mais perto do nível da água. A pressão negativa na entrada da bomba é essa altura de sucção.',
    'Use a submersible pump inside the well, or install the surface pump closer to the water level. The negative pressure at the pump inlet is that suction lift.',
    'Use una bomba sumergible dentro del pozo, o instale la bomba de superficie más cerca del nivel del agua. La presión negativa en la entrada de la bomba es esa altura de succión.',
  ),
  'adv.zone_overlap.why': (
    'Duas zonas estão ligadas por tubo sem válvula entre elas: a água de uma passa para a outra e o programa não consegue separá-las.',
    'Two zones are joined by pipe without a valve between them: the water of one flows into the other and the program cannot tell them apart.',
    'Dos zonas están unidas por tubería sin válvula entre ellas: el agua de una pasa a la otra y el programa no puede separarlas.',
  ),
  'adv.zone_overlap.how': (
    'Corte o tubo que liga as zonas (ferramenta Cortar tubo). Se na verdade são uma zona só, apague uma das válvulas.',
    'Cut the pipe that joins the zones (Cut pipe tool). If they really are a single zone, delete one of the valves.',
    'Corte la tubería que une las zonas (herramienta Cortar tubería). Si en realidad son una sola zona, borre una de las válvulas.',
  ),
  'adv.lp_infeasible.why': (
    'Com os tubos habilitados no catálogo, nenhuma combinação atende todas as pressões ao mesmo tempo; o programa usou o método guloso (aumenta os tubos passo a passo), que dá um bom resultado, mas talvez não o mais barato.',
    'With the pipes enabled in the catalogue, no combination meets every pressure at once; the program used the greedy method (upsizing step by step), which gives a good result but perhaps not the cheapest.',
    'Con las tuberías habilitadas en el catálogo, ninguna combinación cumple todas las presiones a la vez; el programa usó el método voraz (aumenta las tuberías paso a paso), que da un buen resultado, pero quizá no el más barato.',
  ),
  'adv.lp_infeasible.how': (
    'Habilite diâmetros maiores no catálogo, aumente o número de diâmetros por linha nos parâmetros ou reduza a exigência de pressão (zonas menores).',
    'Enable larger diameters in the catalogue, raise the number of diameters per line in the parameters or reduce the pressure demand (smaller zones).',
    'Habilite diámetros mayores en el catálogo, aumente el número de diámetros por línea en los parámetros o reduzca la exigencia de presión (zonas menores).',
  ),
  'adv.fitting_missing.why': (
    'A lista de materiais precisa de uma conexão (luva, joelho, tê…) de um tamanho que o catálogo não tem; ela fica sem preço.',
    'The bill of materials needs a fitting (coupler, elbow, tee…) of a size the catalogue lacks; it stays without a price.',
    'La lista de materiales necesita una conexión (manguito, codo, te…) de un tamaño que el catálogo no tiene; queda sin precio.',
  ),
  'adv.fitting_missing.how': (
    'Adicione as conexões genéricas ao catálogo (correção) ou cadastre as do seu fornecedor no Catálogo de componentes.',
    'Add the generic fittings to the catalogue (correction) or enter those of your supplier in the Component catalog.',
    'Añada las conexiones genéricas al catálogo (corrección) o registre las de su proveedor en el Catálogo de componentes.',
  ),
  'adv.pivot_no_flow.why': (
    'O pivô está com lâmina ou horas por ciclo iguais a zero, então a vazão calculada é zero.',
    'The pivot has a zero depth or zero hours per cycle, so its computed flow is zero.',
    'El pivote tiene lámina u horas por ciclo en cero, así que el caudal calculado es cero.',
  ),
  'adv.pivot_no_flow.how': (
    'Informe a lâmina por ciclo (mm) e as horas por volta nas propriedades do pivô.',
    'Enter the depth per cycle (mm) and the hours per turn in the pivot properties.',
    'Ingrese la lámina por ciclo (mm) y las horas por vuelta en las propiedades del pivote.',
  ),
  'adv.pivot_no_end_pressure.why': (
    'Sem a pressão na ponta (último aspersor) não dá para calcular a pressão de entrada do pivô.',
    'Without the end pressure (last sprinkler) the inlet pressure of the pivot cannot be calculated.',
    'Sin la presión de punta (último aspersor) no se puede calcular la presión de entrada del pivote.',
  ),
  'adv.pivot_no_end_pressure.how': (
    'Informe a pressão de ponta nas propriedades do pivô (típico: 10 a 20 m.c.a. com reguladores).',
    'Enter the end pressure in the pivot properties (typical: 10 to 20 m of head with regulators).',
    'Ingrese la presión de punta en las propiedades del pivote (típico: 10 a 20 m.c.a. con reguladores).',
  ),
  'adv.pivot_app_rate.why': (
    'Na ponta, o pivô aplica água mais rápido do que o solo consegue infiltrar: a água escorre e causa erosão.',
    'At the end the pivot applies water faster than the soil can take it in: the water runs off and causes erosion.',
    'En la punta el pivote aplica agua más rápido de lo que el suelo puede infiltrar: el agua escurre y causa erosión.',
  ),
  'adv.pivot_app_rate.how': (
    'Use aspersores de maior raio molhado na ponta, aumente a velocidade de giro (menos lâmina por volta) ou confira o limite do solo.',
    'Use sprinklers with a larger wetted radius at the end, speed up the rotation (less depth per turn) or check the soil limit.',
    'Use aspersores de mayor radio mojado en la punta, aumente la velocidad de giro (menos lámina por vuelta) o revise el límite del suelo.',
  ),
  'adv.valve_missing.why': (
    'Um turno faz referência a uma válvula que não existe mais (foi apagada).',
    'A system flow refers to a valve that no longer exists (it was deleted).',
    'Un turno hace referencia a una válvula que ya no existe (fue borrada).',
  ),
  'adv.valve_missing.how': (
    'Limpe os turnos (correção) ou abra Projeto → Turnos de operação e retire a válvula do turno.',
    'Clean up the system flows (correction) or open Design → System flows and take the valve out of the flow.',
    'Limpie los turnos (corrección) o abra Diseño → Turnos de operación y quite la válvula del turno.',
  ),
  'adv.set_velocity.why': (
    'Os limites de velocidade nos parâmetros estão fora da faixa física (0,3 a 5 m/s). Zero ou valores enormes tornam o dimensionamento impossível ou sem sentido.',
    'The velocity limits in the parameters are outside the physical range (0.3 to 5 m/s). Zero or huge values make the sizing impossible or meaningless.',
    'Los límites de velocidad de los parámetros están fuera del rango físico (0,3 a 5 m/s). Cero o valores enormes hacen el dimensionamiento imposible o sin sentido.',
  ),
  'adv.set_velocity.how': (
    'Volte aos valores padrão (1,5 m/s nas zonas, 2 m/s nas laterais e na linha principal) ou ajuste em Projeto → Parâmetros de projeto.',
    'Restore the defaults (1.5 m/s in zones, 2 m/s in laterals and the mainline) or adjust them in Design → Design parameters.',
    'Vuelva a los valores por defecto (1,5 m/s en las zonas, 2 m/s en los laterales y en la línea principal) o ajústelos en Diseño → Parámetros de diseño.',
  ),
  'adv.set_hours.why': (
    'As horas de funcionamento por ano estão fora de 1 a 8760 (o ano tem 8760 h). O custo de energia e a escolha dos tubos pelo custo total dependem delas.',
    'The operating hours per year are outside 1 to 8760 (a year has 8760 h). The energy cost and the choice of pipes by total cost depend on them.',
    'Las horas de funcionamiento por año están fuera de 1 a 8760 (el año tiene 8760 h). El costo de energía y la elección de tuberías por costo total dependen de ellas.',
  ),
  'adv.set_hours.how': (
    'Volte aos padrões (2000 h na linha principal, 500 h por zona) ou informe as horas reais em Projeto → Parâmetros de projeto.',
    'Restore the defaults (2000 h for the mainline, 500 h per zone) or enter the real hours in Design → Design parameters.',
    'Vuelva a los valores por defecto (2000 h en la línea principal, 500 h por zona) o ingrese las horas reales en Diseño → Parámetros de diseño.',
  ),
  'adv.set_economy.why': (
    'Algum parâmetro econômico é impossível: juros negativos ou acima de 50 % ao ano, prazo fora de 1 a 100 anos, rendimento da bomba fora de 20 a 95 % ou tarifa de energia negativa.',
    'Some economic parameter is impossible: interest negative or above 50 % a year, a term outside 1 to 100 years, a pump efficiency outside 20 to 95 % or a negative energy tariff.',
    'Algún parámetro económico es imposible: interés negativo o mayor que 50 % al año, plazo fuera de 1 a 100 años, rendimiento de la bomba fuera de 20 a 95 % o tarifa de energía negativa.',
  ),
  'adv.set_economy.how': (
    'Volte aos valores padrão ou corrija em Projeto → Parâmetros de projeto.',
    'Restore the defaults or correct them in Design → Design parameters.',
    'Vuelva a los valores por defecto o corríjalos en Diseño → Parámetros de diseño.',
  ),
  'adv.set_tolerance.why': (
    'A tolerância de conexão diz a que distância dois pontos contam como ligados. Zero não liga nada; valores grandes (mais de 1 m) ligam coisas que deviam estar separadas.',
    'The connection tolerance says how close two points must be to count as joined. Zero joins nothing; large values (over 1 m) join things that should stay apart.',
    'La tolerancia de conexión dice a qué distancia dos puntos cuentan como unidos. Cero no une nada; valores grandes (más de 1 m) unen cosas que deberían estar separadas.',
  ),
  'adv.set_tolerance.how': (
    'Volte ao padrão (5 cm) em Projeto → Parâmetros de projeto.',
    'Restore the default (5 cm) in Design → Design parameters.',
    'Vuelva al valor por defecto (5 cm) en Diseño → Parámetros de diseño.',
  ),
  'adv.set_variation.why': (
    'A variação máxima de pressão na zona está fora de 0 a 60 %. Os critérios usuais ficam entre 10 e 20 % (cerca de ±10 % na vazão).',
    'The maximum pressure variation in the zone is outside 0 to 60 %. The usual criteria are 10 to 20 % (about ±10 % in flow).',
    'La variación máxima de presión en la zona está fuera de 0 a 60 %. Los criterios usuales están entre 10 y 20 % (cerca de ±10 % en el caudal).',
  ),
  'adv.set_variation.how': (
    'Volte ao padrão (0 = usa a faixa de pressão do emissor) ou informe 20 %.',
    'Restore the default (0 = use the pressure range of the emitter) or enter 20 %.',
    'Vuelva al valor por defecto (0 = usa el rango de presión del emisor) o ingrese 20 %.',
  ),
  'adv.set_temperature.why': (
    'A temperatura da água está fora de 0 a 60 °C; ela muda a viscosidade usada na perda de carga (Darcy-Weisbach).',
    'The water temperature is outside 0 to 60 °C; it changes the viscosity used in the friction loss (Darcy-Weisbach).',
    'La temperatura del agua está fuera de 0 a 60 °C; cambia la viscosidad usada en la pérdida de carga (Darcy-Weisbach).',
  ),
  'adv.set_temperature.how': ('Volte ao padrão (20 °C).', 'Restore the default (20 °C).', 'Vuelva al valor por defecto (20 °C).'),
  'adv.no_pipes_for_usage.why': (
    'O catálogo não tem nenhum tubo habilitado para este uso (laterais, zona ou linha principal), então o cálculo não tem diâmetro para escolher.',
    'The catalogue has no pipe enabled for this use (laterals, zone or mainline), so the design has no diameter to choose.',
    'El catálogo no tiene ninguna tubería habilitada para este uso (laterales, zona o línea principal), así que el cálculo no tiene diámetro que elegir.',
  ),
  'adv.no_pipes_for_usage.how': (
    'Habilite tubos no Catálogo de componentes ou use a correção, que reativa os tubos padrão desse uso.',
    'Enable pipes in the Component catalog or use the correction, which re-enables the default pipes of that use.',
    'Habilite tuberías en el Catálogo de componentes o use la corrección, que reactiva las tuberías por defecto de ese uso.',
  ),
  'adv.supply_limits.why': (
    'Na fonte, a pressão ou a vazão de projeto é maior que o máximo informado: um dos valores está trocado ou foi digitado errado.',
    'At the supply, the design pressure or flow is higher than the maximum entered: one of the values is swapped or mistyped.',
    'En la fuente, la presión o el caudal de diseño es mayor que el máximo indicado: uno de los valores está cambiado o mal escrito.',
  ),
  'adv.supply_limits.how': (
    'Confira os valores nas propriedades da fonte; a correção iguala o máximo ao valor de projeto.',
    'Check the values in the supply properties; the correction sets the maximum to the design value.',
    'Revise los valores en las propiedades de la fuente; la corrección iguala el máximo al valor de diseño.',
  ),
  'adv.valve_not_in_flow.why': (
    'Há turnos definidos, mas estas zonas não estão em nenhum: elas nunca abrem na simulação da linha principal e ficam fora da pressão e da energia calculadas.',
    'System flows are defined, but these zones are in none: they never open in the mainline simulation and are left out of the pressures and energy computed.',
    'Hay turnos definidos, pero estas zonas no están en ninguno: nunca abren en la simulación de la línea principal y quedan fuera de la presión y la energía calculadas.',
  ),
  'adv.valve_not_in_flow.how': (
    'Inclua as zonas num turno em Projeto → Turnos de operação, ou use a correção, que cria um turno novo para elas.',
    'Put the zones in a flow in Design → System flows, or use the correction, which creates a new flow for them.',
    'Incluya las zonas en un turno en Diseño → Turnos de operación, o use la corrección, que crea un turno nuevo para ellas.',
  ),
  'adv.flow_empty.why': (
    'Há turnos sem nenhuma zona (vazios ou só com válvulas apagadas): eles não fazem nada e confundem a programação.',
    'Some system flows have no zone (empty or with deleted valves only): they do nothing and confuse the schedule.',
    'Hay turnos sin ninguna zona (vacíos o solo con válvulas borradas): no hacen nada y confunden la programación.',
  ),
  'adv.flow_empty.how': (
    'Limpe os turnos (correção) ou inclua zonas neles em Projeto → Turnos de operação.',
    'Clean up the system flows (correction) or put zones in them in Design → System flows.',
    'Limpie los turnos (corrección) o incluya zonas en ellos en Diseño → Turnos de operación.',
  ),
  'adv.flow_duration.why': (
    'Um turno com duração zero ou negativa não irriga e zera a energia daquele turno.',
    'A system flow with a zero or negative duration irrigates nothing and zeroes its energy.',
    'Un turno con duración cero o negativa no riega y deja en cero la energía de ese turno.',
  ),
  'adv.flow_duration.how': (
    'Informe a duração de cada turno (horas) em Projeto → Turnos de operação; a correção define 1 h.',
    'Enter the duration of each flow (hours) in Design → System flows; the correction sets 1 h.',
    'Ingrese la duración de cada turno (horas) en Diseño → Turnos de operación; la corrección define 1 h.',
  ),
  'adv.emitter_head_range.why': (
    'A pressão de trabalho pedida para o emissor está fora da faixa do bocal (mínima e máxima do catálogo). Assim nenhum tubo consegue deixar a zona dentro da janela de pressão: a zona fica impossível.',
    'The working pressure asked for the emitter is outside the nozzle range (catalogue minimum and maximum). Then no pipe can keep the zone inside its pressure window: the zone becomes impossible.',
    'La presión de trabajo pedida para el emisor está fuera del rango de la boquilla (mínima y máxima del catálogo). Así ninguna tubería puede dejar la zona dentro de la ventana de presión: la zona se vuelve imposible.',
  ),
  'adv.emitter_head_range.how': (
    'Use a pressão nominal do bocal (correção) ou escolha outro bocal ou emissor feito para a pressão desejada.',
    'Use the nominal pressure of the nozzle (correction) or choose another nozzle or emitter made for the pressure you want.',
    'Use la presión nominal de la boquilla (corrección) o elija otra boquilla o emisor hecho para la presión deseada.',
  ),
  'adv.pump_speed.why': (
    'A rotação relativa da bomba está fora de 40 a 130 % da nominal; pelas leis de afinidade, a curva vira algo que a bomba real não faz.',
    'The relative pump speed is outside 40 to 130 % of the rated one; by the affinity laws the curve becomes something the real pump cannot do.',
    'La velocidad relativa de la bomba está fuera de 40 a 130 % de la nominal; por las leyes de afinidad, la curva se vuelve algo que la bomba real no hace.',
  ),
  'adv.pump_speed.how': (
    'Volte à rotação nominal (1,0) ou use o inversor de frequência só dentro da faixa do fabricante.',
    'Go back to the rated speed (1.0) or use a variable-speed drive only within the range of the manufacturer.',
    'Vuelva a la velocidad nominal (1,0) o use el variador de frecuencia solo dentro del rango del fabricante.',
  ),
