  'cat.packs': ('Catálogos de fabricantes…', 'Manufacturer catalogues…', 'Catálogos de fabricantes…'),
  'cat.packsExplain': (
    'Produtos com os dados das tabelas publicadas pelos fabricantes (vazão, expoente, raio, faixa de pressão, perda de carga) e os documentos de origem de cada pacote. Os preços ficam em zero: exporte para Excel, preencha com a tabela local e importe de volta. Confirme sempre na folha de dados atual.',
