  'file.examples': ('Exemplos', 'Examples', 'Ejemplos'),
  'help.welcome': ('Boas-vindas e galeria de exemplos…', 'Welcome and example gallery…', 'Bienvenida y galería de ejemplos…'),
  'welcome.title': ('Bem-vindo ao OpenCADIrrigation', 'Welcome to OpenCADIrrigation', 'Bienvenido a OpenCADIrrigation'),
  'welcome.body': (
    'CAD para projeto de irrigação pressurizada, direto no navegador. Comece por um exemplo pronto ou faça o tutorial interativo: ele começa localizando a sua área no mapa de satélite e baixando o relevo da internet, e segue em 76 passos curtos em que você mesmo navega, desenha, monta a rede e projeta; cada passo reconhece quando você o completou e avança sozinho. Leva uns 20 minutos e pode ser pulado a qualquer momento (Ajuda → Tutorial interativo reabre depois).',
    'CAD for pressurised irrigation design, right in the browser. Start from a ready example or take the interactive tutorial: it begins by locating your site on the satellite map and downloading the terrain from the internet, then goes on in 76 short steps in which you navigate, draw, build the network and design it yourself; each step recognises when you have completed it and moves on. It takes about 20 minutes and can be skipped at any time (Help → Interactive tutorial reopens it).',
    'CAD para diseño de riego presurizado, directamente en el navegador. Empiece por un ejemplo listo o haga el tutorial interactivo: comienza ubicando su área en el mapa satelital y descargando el relieve de internet, y sigue en 76 pasos cortos en los que usted mismo navega, dibuja, arma la red y diseña; cada paso reconoce cuando lo completó y avanza solo. Tarda unos 20 minutos y puede omitirse en cualquier momento (Ayuda → Tutorial interactivo lo reabre).',
  ),
  'welcome.examples': ('Comece por um exemplo', 'Start from an example', 'Empiece por un ejemplo'),
  'welcome.examplesHint': (
    'Cada projeto abre pronto para calcular: pressione F5 ou ▶ e veja zonas, pressões, diâmetros e lista de materiais. Arquivo → Exemplos reabre qualquer um deles.',
    'Each project opens ready to design: press F5 or ▶ and see zones, pressures, pipe sizes and the bill of materials. File → Examples reopens any of them.',
    'Cada proyecto se abre listo para calcular: pulse F5 o ▶ y vea zonas, presiones, diámetros y lista de materiales. Archivo → Ejemplos reabre cualquiera de ellos.',
  ),
  'welcome.tutorial': ('Iniciar tutorial', 'Start tutorial', 'Iniciar tutorial'),
