  'adv.elec_no_controller.why': (
    'Há rotas de fios, mas nenhum controlador: sem ele não há de onde partir a tensão das válvulas nem como dimensionar os fios.',
    'There are wire routes but no controller: without it there is nowhere for the valve voltage to come from and no way to size the wires.',
    'Hay rutas de cables pero ningún controlador: sin él no hay de dónde salga la tensión de las válvulas ni cómo dimensionar los cables.',
  ),
  'adv.elec_no_controller.how': (
    'Coloque um controlador (CTRL) sobre o início de uma rota de fios.',
    'Place a controller (CTRL) on the start of a wire route.',
    'Coloque un controlador (CTRL) sobre el inicio de una ruta de cables.',
  ),
  'adv.elec_unwired.why': (
    'A válvula não está em nenhuma rota de fios ligada a um controlador, então não terá estação nem fio no orçamento e não abrirá sozinha.',
    'The valve is on no wire route connected to a controller, so it gets no station and no wire in the bill of materials and will not open by itself.',
    'La válvula no está en ninguna ruta de cables conectada a un controlador, así que no tendrá estación ni cable en el presupuesto y no se abrirá sola.',
  ),
  'adv.elec_unwired.how': (
    'Estenda uma rota de fios (WR) até a válvula, terminando exatamente sobre ela ou passando por ela.',
    'Extend a wire route (WR) to the valve, ending exactly on it or passing through it.',
    'Extienda una ruta de cables (WR) hasta la válvula, terminando exactamente sobre ella o pasando por ella.',
  ),
  'adv.elec_wire_orphan.why': (
    'Esta rota de fios não se liga a nenhum controlador (nem por outra rota); os fios dela não entram no cálculo.',
    'This wire route connects to no controller (not even through another route); its wires are left out of the design.',
    'Esta ruta de cables no se conecta a ningún controlador (ni por otra ruta); sus cables quedan fuera del cálculo.',
  ),
  'adv.elec_wire_orphan.how': (
    'Ligue a rota a outra rota por um vértice comum ou até um controlador, ou apague-a se sobrou.',
    'Join the route to another one at a shared vertex or to a controller, or delete it if it is left over.',
    'Una la ruta a otra por un vértice común o hasta un controlador, o bórrela si sobra.',
  ),
  'adv.elec_ctrl_unwired.why': (
    'O controlador não está sobre nenhuma rota de fios, então não aciona nenhuma válvula.',
    'The controller is on no wire route, so it drives no valve.',
    'El controlador no está sobre ninguna ruta de cables, así que no acciona ninguna válvula.',
  ),
  'adv.elec_ctrl_unwired.how': (
    'Mova o controlador para o início de uma rota ou desenhe uma rota (WR) a partir dele.',
    'Move the controller to the start of a route or draw a route (WR) from it.',
    'Mueva el controlador al inicio de una ruta o dibuje una ruta (WR) desde él.',
  ),
  'adv.elec_no_wires.why': (
    'O catálogo não tem fios habilitados; o cálculo supôs um fio de cobre de 1,5 mm² e não pôs fios no orçamento.',
    'The catalogue has no wire enabled; the design assumed a 1.5 mm² copper wire and left the wires out of the bill of materials.',
    'El catálogo no tiene cables habilitados; el cálculo supuso un cable de cobre de 1,5 mm² y dejó los cables fuera del presupuesto.',
  ),
  'adv.elec_no_wires.how': (
    'Habilite fios no catálogo (aba Fios) ou restaure os fios padrão.',
    'Enable wires in the catalogue (Wires tab) or restore the default wires.',
    'Habilite cables en el catálogo (pestaña Cables) o restaure los cables por defecto.',
  ),
  'adv.elec_stations.why': (
    'Há mais válvulas ligadas ao controlador do que estações: algumas zonas ficariam sem saída para abrir.',
    'More valves are wired to the controller than it has stations: some zones would have no output to open them.',
    'Hay más válvulas conectadas al controlador que estaciones: algunas zonas quedarían sin salida para abrirlas.',
  ),
  'adv.elec_stations.how': (
    'Use um controlador com mais estações (ou um módulo de expansão), ou divida as válvulas entre dois controladores.',
    'Use a controller with more stations (or an expansion module), or split the valves between two controllers.',
    'Use un controlador con más estaciones (o un módulo de expansión), o divida las válvulas entre dos controladores.',
  ),
  'adv.elec_voltage.why': (
    'Mesmo com o fio mais grosso habilitado, a queda de tensão no fio de estação e no comum deixa o solenoide abaixo da tensão mínima ao abrir: a válvula pode não abrir ou zumbir.',
    'Even with the thickest enabled wire, the voltage drop in the station and common wires leaves the solenoid below the minimum voltage while opening: the valve may not open or may chatter.',
    'Aun con el cable más grueso habilitado, la caída de tensión en el cable de estación y en el común deja el solenoide por debajo de la tensión mínima al abrir: la válvula puede no abrir o vibrar.',
  ),
  'adv.elec_voltage.how': (
    'Habilite fios mais grossos no catálogo, aproxime o controlador das válvulas, reduza as válvulas abertas juntas no mesmo comum ou use um controlador de dois fios (decodificadores).',
    'Enable thicker wires in the catalogue, bring the controller closer to the valves, open fewer valves together on the same common or use a two-wire (decoder) controller.',
    'Habilite cables más gruesos en el catálogo, acerque el controlador a las válvulas, abra menos válvulas juntas en el mismo común o use un controlador de dos hilos (decodificadores).',
  ),
