  'share.hint': (
    'O projeto inteiro vai dentro do próprio endereço, comprimido, na parte depois do # (que o navegador não envia a nenhum servidor): quem abrir o link recebe uma cópia numa aba nova. Imagens de fundo e resultados ficam de fora; quem recebe calcula de novo.',
