  'dens.windHint': (
    'Estimativa de primeira ordem: cada gota cai mais longe a favor do vento, em proporção à velocidade e ao alcance (coeficiente 0,07 s/m); para projeto fino, use perfis medidos com vento.',
    'First-order estimate: every drop lands further downwind in proportion to the wind speed and its throw (coefficient 0.07 s/m); for fine design, use profiles measured in wind.',
    'Estimación de primer orden: cada gota cae más lejos a favor del viento, en proporción a la velocidad y a su alcance (coeficiente 0,07 s/m); para diseño fino, use perfiles medidos con viento.',
