  'cat.profile': ('Perfil medido (ensaio de coletores)', 'Measured profile (catch-can test)', 'Perfil medido (ensayo de pluviómetros)'),
  'cat.profileHint': (
    'Cole as linhas do ensaio: distância do aspersor ({r}) e lâmina ou intensidade na distância (qualquer unidade). O perfil é escalado ao raio molhado e à maior lâmina e passa a ser usado no densograma.',
    'Paste the rows of the test: distance from the sprinkler ({r}) and the depth or rate at that distance (any unit). The profile is scaled to the wetted radius and to the largest depth and used by the densogram.',
    'Pegue las filas del ensayo: distancia del aspersor ({r}) y lámina o intensidad a esa distancia (cualquier unidad). El perfil se escala al radio mojado y a la mayor lámina y lo usa el densograma.',
