  'warn.pump_npsh': (
    'NPSH disponível abaixo do requerido pela bomba (risco de cavitação)',
    'NPSH available below what the pump requires (cavitation risk)',
    'NPSH disponible por debajo del requerido por la bomba (riesgo de cavitación)',
  ),
  'warn.vfd_target_unreachable': (
    'O inversor não alcança a pressão alvo nem na rotação máxima',
    'The drive cannot reach the target pressure even at full speed',
    'El variador no alcanza la presión objetivo ni a la velocidad máxima',
  ),
  'warn.vfd_below_min_speed': (
    'A pressão alvo pede rotação abaixo da mínima do inversor',
    'The target pressure asks for less than the drive\'s minimum speed',
    'La presión objetivo pide una velocidad por debajo de la mínima del variador',
  ),
  'adv.pump_npsh.why': (
    'A pressão absoluta na entrada da bomba, menos a pressão de vapor da água, fica abaixo do NPSH que a bomba exige nessa vazão: a água vaporiza no rotor (cavitação), a bomba perde altura, faz barulho e se desgasta.',
    'The absolute pressure at the pump inlet, less the vapour pressure of the water, is below the NPSH the pump needs at that flow: the water flashes in the impeller (cavitation), the pump loses head, gets noisy and wears.',
    'La presión absoluta a la entrada de la bomba, menos la presión de vapor del agua, queda por debajo del NPSH que la bomba exige a ese caudal: el agua se vaporiza en el rodete (cavitación), la bomba pierde altura, hace ruido y se desgasta.',
  ),
  'adv.pump_npsh.how': (
    'Baixe a bomba para perto do nível da água ou use uma submersa, aumente o diâmetro e encurte a sucção, ou escolha uma bomba de NPSH requerido menor nessa vazão.',
    'Lower the pump towards the water level or use a submersible one, enlarge and shorten the suction pipe, or choose a pump with a lower required NPSH at that flow.',
    'Baje la bomba hacia el nivel del agua o use una sumergible, aumente el diámetro y acorte la succión, o elija una bomba de NPSH requerido menor a ese caudal.',
  ),
  'adv.vfd_target_unreachable.why': (
    'Mesmo na rotação máxima a bomba não entrega a pressão que o inversor deveria manter na saída com a vazão deste turno.',
    'Even at full speed the pump does not deliver the pressure the drive should hold at its outlet with the flow of this system flow.',
    'Incluso a la velocidad máxima la bomba no entrega la presión que el variador debería mantener a la salida con el caudal de este turno.',
  ),
  'adv.vfd_target_unreachable.how': (
    'Baixe a pressão alvo, divida o turno ou escolha uma bomba maior.',
    'Lower the target pressure, split the system flow or choose a larger pump.',
    'Baje la presión objetivo, divida el turno o elija una bomba mayor.',
  ),
  'adv.vfd_below_min_speed.why': (
    'Neste turno a bomba entrega a pressão alvo abaixo da rotação mínima do inversor; ela gira na mínima e a pressão fica acima do alvo.',
    'In this system flow the pump delivers the target pressure below the drive\'s minimum speed; it runs at the minimum and the pressure stays above the target.',
    'En este turno la bomba entrega la presión objetivo por debajo de la velocidad mínima del variador; gira a la mínima y la presión queda por encima del objetivo.',
  ),
  'adv.vfd_below_min_speed.how': (
    'Agrupe mais zonas no turno, baixe a rotação mínima se o fabricante permitir, ou aceite a pressão um pouco maior.',
    'Group more zones in the flow, lower the minimum speed if the maker allows it, or accept the slightly higher pressure.',
    'Agrupe más zonas en el turno, baje la velocidad mínima si el fabricante lo permite, o acepte la presión algo mayor.',
  ),
  'props.vfdTarget': ('Inversor: pressão na saída (0 = rotação fixa)', 'Drive: outlet pressure (0 = fixed speed)', 'Variador: presión a la salida (0 = velocidad fija)'),
