  'adv.vfd_target_low.why': (
    'Com o inversor mantendo esta pressão na saída, a válvula mais exigente do turno fica sem a pressão que pede; o cálculo mostra quanto faltaria na fonte.',
    'With the drive holding this outlet pressure, the most demanding valve of the flow lacks the pressure it asks for; the design shows how much the supply would have to add.',
    'Con el variador manteniendo esta presión a la salida, la válvula más exigente del turno queda sin la presión que pide; el cálculo muestra cuánto faltaría en la fuente.',
