  'warn.pivot_elec_no_towers': ('Pivô sem torres para o projeto elétrico', 'Pivot without towers for the electrical design', 'Pivote sin torres para el diseño eléctrico'),
  'warn.pivot_elec_start_drop': (
    'Queda de tensão na partida dos motores acima do limite',
    'Voltage drop while the motors start above the limit',
    'Caída de tensión en el arranque de los motores por encima del límite',
  ),
  'adv.pivot_pkg_pressure.why': (
    'O pacote de aspersores calcula, saída por saída, a pressão que chega a cada regulador e bocal com o atrito, o desnível, a altura dos tubos e os pendurais. Um regulador só regula com pelo menos 5 psi acima da sua classificação; abaixo disso os bocais recebem menos pressão e vazão.',
    'The sprinkler package works out, outlet by outlet, the pressure that reaches every regulator and nozzle with the friction, the ground rise, the pipe height and the drops. A regulator only regulates with at least 5 psi above its rating; below that the nozzles get less pressure and flow.',
    'El paquete de aspersores calcula, salida por salida, la presión que llega a cada regulador y boquilla con la fricción, el desnivel, la altura de los tubos y las bajantes. Un regulador solo regula con al menos 5 psi por encima de su calibre; por debajo las boquillas reciben menos presión y caudal.',
  ),
  'adv.pivot_pkg_pressure.how': (
    'Dimensione a bomba e a adutora para a pressão de entrada que o pacote pede (o cálculo da linha principal já usa esse valor), escolha reguladores de classificação menor ou confira a pressão de ponta e a altura dos bocais no pacote do pivô.',
    'Size the pump and the supply main for the inlet pressure the package asks for (the mainline design already uses it), choose regulators of a lower rating or check the end pressure and the nozzle height in the pivot package.',
    'Dimensione la bomba y la aductora para la presión de entrada que pide el paquete (el cálculo de la línea principal ya usa ese valor), elija reguladores de calibre menor o revise la presión de punta y la altura de las boquillas en el paquete del pivote.',
  ),
  'adv.pivot_pkg_nozzles.why': (
    'Cada saída do pivô precisa de uma vazão proporcional à área que molha (Heermann e Hein). O bocal escolhido é o de vazão mais próxima à pressão da saída; quando a série de bocais é grossa, curta ou a pressão sai da faixa, a lâmina deixa de ser uniforme ao longo da máquina.',
    'Every outlet of the pivot needs a flow proportional to the area it waters (Heermann and Hein). The chosen nozzle is the one whose flow is closest at the outlet pressure; when the nozzle series is coarse or short, or the pressure leaves its range, the depth stops being even along the machine.',
    'Cada salida del pivote necesita un caudal proporcional al área que moja (Heermann y Hein). La boquilla elegida es la de caudal más cercano a la presión de la salida; cuando la serie de boquillas es gruesa o corta, o la presión sale de su rango, la lámina deja de ser uniforme a lo largo de la máquina.',
  ),
  'adv.pivot_pkg_nozzles.how': (
    'Use a série numerada de bocais (sem aspersor do catálogo) ou um aspersor com mais bocais, amplie a faixa de números, ou reduza o espaçamento das saídas no fim da máquina.',
    'Use the numbered nozzle series (no catalogue sprinkler) or a sprinkler with more nozzles, widen the range of numbers, or reduce the outlet spacing at the end of the machine.',
    'Use la serie numerada de boquillas (sin aspersor del catálogo) o un aspersor con más boquillas, amplíe el rango de números o reduzca el espaciamiento de las salidas al final de la máquina.',
  ),
  'adv.pivot_pkg_setup.why': (
    'O pacote de aspersores precisa de saídas ao longo dos vãos, de uma vazão (lâmina e horas por ciclo) e, com canhão final, da vazão ou do raio do canhão.',
    'The sprinkler package needs outlets along the spans, a flow (depth and hours per cycle) and, with an end gun, the gun\'s flow or radius.',
    'El paquete de aspersores necesita salidas a lo largo de los vanos, un caudal (lámina y horas por ciclo) y, con cañón final, el caudal o el radio del cañón.',
  ),
  'adv.pivot_pkg_setup.how': (
    'Confira nas propriedades do pivô o comprimento, os vãos, o espaçamento dos aspersores, a lâmina e as horas por ciclo; no pacote do pivô, informe o canhão final ou desligue-o.',
    'Check the length, the spans, the sprinkler spacing, the depth and the hours per cycle in the pivot properties; in the pivot package, enter the end gun or switch it off.',
    'Revise en las propiedades del pivote la longitud, los vanos, el espaciamiento de los aspersores, la lámina y las horas por ciclo; en el paquete del pivote, indique el cañón final o desactívelo.',
  ),
  'adv.pivot_pkg_no_drive.why': (
    'A tabela do temporizador (horas por volta e lâmina em cada ajuste) vem da velocidade da última torre a 100 %, que depende do motor, das reduções e do pneu.',
    'The timer chart (hours per revolution and depth at each setting) comes from the speed of the last tower at 100 %, which depends on the motor, the gearboxes and the tyre.',
    'La tabla del temporizador (horas por vuelta y lámina en cada ajuste) viene de la velocidad de la última torre al 100 %, que depende del motor, las reducciones y el neumático.',
  ),
  'adv.pivot_pkg_no_drive.how': (
    'No pacote do pivô, informe a rotação do motor, as reduções e o diâmetro do pneu, ou a velocidade da última torre a 100 % dada pelo fabricante.',
    'In the pivot package, enter the motor speed, the gear ratios and the tyre diameter, or the speed of the last tower at 100 % given by the manufacturer.',
    'En el paquete del pivote, indique la rotación del motor, las reducciones y el diámetro del neumático, o la velocidad de la última torre al 100 % dada por el fabricante.',
  ),
  'adv.corner_arm.why': (
    'O braço de canto gira na última torre e sua ponta segue uma trajetória-guia (o contorno do campo recuado), abrindo-se nos cantos. Fora do alcance do braço esticado ou dobrado, a ponta não acompanha a trajetória e parte do canto fica sem irrigação ou com sobreposição.',
    'The corner arm swings at the last tower and its tip follows a guide path (the field outline set back), opening into the corners. Beyond the reach of the straight or folded arm the tip cannot follow the path and part of the corner is left dry or overlapped.',
    'El brazo de esquina gira en la última torre y su punta sigue una trayectoria guía (el contorno del campo retranqueado), abriéndose en las esquinas. Fuera del alcance del brazo extendido o plegado la punta no sigue la trayectoria y parte de la esquina queda sin riego o con solapamiento.',
  ),
  'adv.corner_arm.how': (
    'Escolha como guia um contorno fechado em volta do ponto do pivô, ajuste o recuo, o comprimento do braço ou o ângulo máximo de dobra; confira a lâmina e as horas por ciclo do pivô.',
    'Choose as guide a closed outline around the pivot point, adjust the set-back, the arm length or the largest folding angle; check the depth and hours per cycle of the pivot.',
    'Elija como guía un contorno cerrado alrededor del punto del pivote, ajuste el retranqueo, la longitud del brazo o el ángulo máximo de plegado; revise la lámina y las horas por ciclo del pivote.',
  ),
  'adv.vri_limits.why': (
    'Na irrigação de taxa variável a lâmina de cada setor sai do ajuste do temporizador: a 100 % o pivô aplica a menor lâmina possível e no ajuste mais lento, a maior. Alvos fora dessa faixa são limitados.',
    'In variable-rate irrigation the depth of each sector comes from the timer setting: at 100 % the pivot applies the smallest possible depth and at the slowest setting the largest. Targets outside that range are capped.',
    'En el riego de tasa variable la lámina de cada sector sale del ajuste del temporizador: al 100 % el pivote aplica la menor lámina posible y en el ajuste más lento, la mayor. Los objetivos fuera de ese rango se limitan.',
  ),
  'adv.vri_limits.how': (
    'Informe a velocidade da última torre, revise as lâminas da prescrição ou o ajuste mais lento aceito pelo painel; para lâminas menores que a de 100 %, use controle por zonas (bancos de aspersores).',
    'Enter the speed of the last tower, review the prescription depths or the slowest setting the panel accepts; for depths smaller than the one at 100 %, use zone control (sprinkler banks).',
    'Indique la velocidad de la última torre, revise las láminas de la prescripción o el ajuste más lento que acepta el panel; para láminas menores que la del 100 %, use control por zonas (bancos de aspersores).',
  ),
  'adv.pivot_elec_drop.why': (
    'Os motores das torres ficam no fim de um cabo longo: a corrente de todos passa pelos primeiros vãos e a tensão cai ao longo da máquina, mais ainda na partida de um motor. Abaixo do limite os motores aquecem ou não partem.',
    'The tower motors sit at the end of a long cable: the current of all of them goes through the first spans and the voltage drops along the machine, even more while a motor starts. Below the limit the motors overheat or fail to start.',
    'Los motores de las torres están al final de un cable largo: la corriente de todos pasa por los primeros vanos y la tensión cae a lo largo de la máquina, aún más en el arranque de un motor. Por debajo del límite los motores se calientan o no arrancan.',
  ),
  'adv.pivot_elec_drop.how': (
    'Aumente a seção do cabo dos vãos ou do cabo de alimentação, encurte a alimentação, use tensão maior ou motores de menor potência.',
    'Increase the section of the span cable or of the supply cable, shorten the supply, use a higher voltage or lower-power motors.',
    'Aumente la sección del cable de los vanos o del cable de alimentación, acorte la alimentación, use una tensión mayor o motores de menor potencia.',
  ),
