  'od.title': ('Linha principal sob demanda', 'Mainline on demand', 'Línea principal a la demanda'),
  'od.hint': (
    'Cada válvula de zona ou pivô vira um hidrante que o usuário abre quando precisa, aberto com a probabilidade das suas horas de uso por dia (p = horas / (24·r)). A vazão de cada trecho, não excedida com a qualidade de funcionamento pedida, vem da primeira fórmula de Clément e é comparada com a dos turnos para os quais o projeto dimensionou os tubos (FAO Irrigação e Drenagem 59). A verificação aleatória resolve a rede para hidrantes abertos ao acaso.',
    'Every zone valve or pivot becomes a hydrant its user opens whenever needed, open with the probability of its hours of use a day (p = hours / (24·r)). The flow of every section, not exceeded with the operating quality asked, comes from Clément\'s first formula and is compared with that of the system flows the design sized the pipes for (FAO Irrigation and Drainage Paper 59). The random check solves the network for hydrants opened at random.',
    'Cada válvula de sector o pivote se vuelve un hidrante que su usuario abre cuando lo necesita, abierto con la probabilidad de sus horas de uso por día (p = horas / (24·r)). El caudal de cada tramo, no superado con la calidad de funcionamiento pedida, sale de la primera fórmula de Clément y se compara con el de los turnos para los que el diseño dimensionó las tuberías (FAO Riego y Drenaje 59). La verificación aleatoria resuelve la red para hidrantes abiertos al azar.',
  ),
