  'tar.title': ('Tarifa horária de energia', 'Time-of-use energy tariff', 'Tarifa horaria de energía'),
  'tar.hint': (
    'Preço da energia por faixa do dia (ponta e fora de ponta), tarifas de demanda e o desconto da irrigação numa janela do dia, como na tarifa rural de irrigação do Brasil. Os turnos funcionam um de cada vez, todos os dias; o cálculo escolhe os horários de início e os blocos do desconto que custam menos e compara com os horários atuais. Aplicar muda só os horários de início dos turnos.',
    'Energy price by band of the day (peak and off-peak), demand charges and the irrigation discount in a window of the day, as in the Brazilian rural irrigation tariff. The system flows run one at a time, every day; the calculation chooses the start times and the discount blocks that cost least and compares them with the current start hours. Apply only changes the start hours of the system flows.',
    'Precio de la energía por franja del día (punta y fuera de punta), cargos por demanda y el descuento del riego en una ventana del día, como en la tarifa rural de riego de Brasil. Los turnos funcionan uno por vez, todos los días; el cálculo elige los horarios de inicio y los bloques del descuento que cuestan menos y los compara con los horarios actuales. Aplicar solo cambia los horarios de inicio de los turnos.',
  ),
