  'tar.applied': ('Horários de início de {n} turno(s) alterados', 'Start hours of {n} system flow(s) changed', 'Horarios de inicio de {n} turno(s) cambiados'),
  'eg.title': ('Turnos de menor consumo de energia', 'System flows that use the least energy', 'Turnos de menor consumo de energía'),
  'eg.hint': (
    'A bomba de um turno entrega a maior pressão de que qualquer zona dele precisa, e as zonas que precisam de menos recebem mais do que usam: juntar zonas de necessidade parecida economiza energia. A busca respeita a vazão máxima de cada turno, o número de turnos e as horas por dia; as pressões vêm da linha principal resolvida como no projeto. Aplicar substitui os turnos.',
    'The pump of a system flow delivers the highest pressure any of its zones needs, and the zones that need less get more than they use: grouping zones of similar need saves energy. The search keeps within the most flow of a system flow, the number of system flows and the hours a day; the pressures come from the mainline solved as the design does. Apply replaces the system flows.',
    'La bomba de un turno entrega la mayor presión que necesita cualquiera de sus sectores, y los sectores que necesitan menos reciben más de lo que usan: juntar sectores de necesidad parecida ahorra energía. La búsqueda respeta el caudal máximo de cada turno, el número de turnos y las horas por día; las presiones salen de la línea principal resuelta como en el diseño. Aplicar sustituye los turnos.',
  ),
