  'wr.title': ('Rotas automáticas de fios', 'Automatic wire routes', 'Rutas automáticas de cables'),
  'wr.hint': (
    'Os fios seguem as valas dos tubos, de cada controlador até as suas válvulas, válvulas mestras e relés de partida da bomba (cada item no controlador mais próximo pelas valas); as estações são numeradas pela distância. Caminhos mínimos dão a cada fio de estação o menor comprimento; a árvore de menor comprimento total serve ao sistema de dois fios. Desenhar cria as rotas como fios do projeto, que o dimensionamento elétrico segue.',
    'The wires follow the pipe trenches from every controller to its valves, master valves and pump-start relays (each to the controller nearest along the trenches); the stations are numbered by distance. Shortest paths give every station wire the least length; the tree of least total length suits a two-wire system. Draw creates the routes as wire routes of the project, which the valve wiring design follows.',
    'Los cables siguen las zanjas de las tuberías, de cada controlador a sus válvulas, válvulas maestras y relés de arranque de la bomba (cada uno al controlador más cercano por las zanjas); las estaciones se numeran por distancia. Los caminos mínimos dan a cada cable de estación la menor longitud; el árbol de menor longitud total sirve al sistema de dos hilos. Dibujar crea las rutas como cables del proyecto, que el diseño eléctrico sigue.',
  ),
