  'tw.title': ('Sistema de dois fios (decodificadores)', 'Two-wire system (decoders)', 'Sistema de dos hilos (decodificadores)'),
  'tw.hint': (
    'Um par de condutores sai do controlador e passa por todas as válvulas; um decodificador emendado no par aciona 1, 2, 4 ou 6 solenoides próximos. O fio escolhido é o mais barato da lista que mantém cada decodificador acima da tensão mínima enquanto uma estação abre com as outras do turno ligadas. Valores típicos: confira-os com os catálogos do controlador e dos decodificadores.',
    'A pair of conductors leaves the controller and passes every valve; a decoder spliced on the pair drives 1, 2, 4 or 6 nearby solenoids. The wire chosen is the cheapest of the list that keeps every decoder above the minimum voltage while a station opens with the others of its flow on. Typical values: check them against the data sheets of the controller and the decoders.',
    'Un par de conductores sale del controlador y pasa por todas las válvulas; un decodificador empalmado en el par acciona 1, 2, 4 o 6 solenoides cercanos. El cable elegido es el más barato de la lista que mantiene cada decodificador sobre la tensión mínima mientras una estación abre con las demás del turno encendidas. Valores típicos: verifíquelos con los catálogos del controlador y de los decodificadores.',
  ),
