  'crit.title': ('Criticidade dos tubos da linha principal', 'Criticality of the mainline pipes', 'Criticidad de las tuberías de la línea principal'),
  'crit.hint': (
    'Cada tubo da linha principal sai de serviço por vez (um vazamento, um reparo) com o turno escolhido aberto: as zonas que perdem a fonte, as que ficam abaixo da pressão de que precisam e quanto da sua vazão uma solução por pressão ainda entrega. Numa linha ramificada todo tubo corta o que está a jusante; as malhas dão caminhos alternativos.',
    'Every mainline pipe goes out of service in turn (a leak, a repair) with the chosen system flow open: the zones that lose the supply, those left below the pressure they need and how much of their flow a pressure-driven solution still delivers. In a branched mainline every pipe cuts off what lies downstream; loops give other ways.',
    'Cada tubería de la línea principal sale de servicio por vez (una fuga, una reparación) con el turno elegido abierto: los sectores que pierden la fuente, los que quedan bajo la presión que necesitan y cuánto de su caudal todavía entrega una solución por presión. En una línea ramificada toda tubería corta lo que está aguas abajo; las mallas dan caminos alternativos.',
  ),
