  'crit.short': ('Zonas sem pressão (déficit, % entregue)', 'Zones short of pressure (deficit, % delivered)', 'Sectores sin presión (déficit, % entregado)'),
  'cal.title': ('Calibração da rugosidade (C de Hazen-Williams)', 'Roughness calibration (Hazen-Williams C)', 'Calibración de la rugosidad (C de Hazen-Williams)'),
  'cal.hint': (
    'Digite as pressões lidas no campo em pontos da linha principal e as vazões que saem das fontes enquanto o turno escolhido funcionava. O cálculo procura o fator do C de todos os tubos que melhor reproduz as leituras (mínimos quadrados ponderados por σ, com a rede resolvida a cada tentativa). A pressão lida numa fonte é a que a rede recebe: leia-a também. Aplicar muda a escala do C nos parâmetros do projeto.',
    'Type the pressures read in the field at points of the mainline and the flows leaving the supplies while the chosen system flow ran. The calculation seeks the factor on the C of every pipe that best reproduces the readings (least squares weighted by σ, the network solved at every try). The pressure read at a supply is what the network receives: read it too. Apply changes the C scale of the design parameters.',
    'Escriba las presiones leídas en el campo en puntos de la línea principal y los caudales que salen de las fuentes mientras funcionaba el turno elegido. El cálculo busca el factor del C de todas las tuberías que mejor reproduce las lecturas (mínimos cuadrados ponderados por σ, con la red resuelta en cada intento). La presión leída en una fuente es la que recibe la red: léala también. Aplicar cambia la escala del C en los parámetros del diseño.',
  ),
  'cal.none': ('O projeto não tem fonte de água na linha principal.', 'The design has no water supply on the mainline.', 'El diseño no tiene fuente de agua en la línea principal.'),
