  'fert.title': ('Fertirrigação', 'Fertigation', 'Fertirrigación'),
  'fert.hint': (
    'O produto injetado numa fonte ou na saída de uma bomba avança com a água (fluxo pistão pelas vazões do projeto): tempo até cada válvula do turno e até o emissor mais distante de cada zona. A injeção começa depois da pré-irrigação e para cedo o bastante para a água limpa expulsar o produto de todos os tubos antes do fim da irrigação.',
    'The product injected at a supply or at a pump outlet travels with the water (plug flow along the design flows): time to every valve of the system flow and to the farthest emitter of each zone. The injection starts after the pre-wetting and stops early enough for clean water to flush the product out of every pipe before the irrigation ends.',
    'El producto inyectado en una fuente o a la salida de una bomba avanza con el agua (flujo pistón por los caudales del diseño): tiempo hasta cada válvula del turno y hasta el emisor más lejano de cada sector. La inyección empieza después del prerriego y para con tiempo para que el agua limpia expulse el producto de todas las tuberías antes del fin del riego.',
  ),
