  'warn.vih_pressure_high': (
    'Pressão acima da faixa no aspersor com válvula incorporada',
    'Pressure above the window at a valve-in-head sprinkler',
    'Presión por encima del rango en el aspersor con válvula incorporada',
  ),
  'check.vih_not_in_flow': (
    'Estações de aspersores com válvula incorporada fora de todos os turnos (funcionam em todos)',
    'Valve-in-head stations in no system flow (they run in every flow)',
    'Estaciones de aspersores con válvula incorporada fuera de todos los turnos (funcionan en todos)',
  ),
  'adv.vih_not_in_flow.why': (
    'Há turnos definidos, mas estas estações de aspersores com válvula incorporada não estão em nenhum: uma estação sem turno abre em todos os turnos, a vazão dela soma-se à de cada turno e a pressão dela não entra no cálculo da fonte.',
    'System flows are defined, but these valve-in-head stations are in none: a station in no flow opens in every flow, its flow adds to that of each flow and its pressure does not count for the supply.',
    'Hay turnos definidos, pero estas estaciones de aspersores con válvula incorporada no están en ninguno: una estación sin turno abre en todos los turnos, su caudal se suma al de cada turno y su presión no cuenta para la fuente.',
  ),
  'adv.vih_not_in_flow.how': (
    'Inclua as estações nos turnos em Projeto → Turnos de operação (o agrupamento automático também as distribui) ou, se devem mesmo funcionar sempre, ignore este aviso.',
    'Put the stations in flows in Design → System flows (the automatic grouping places them too) or, if they really run all the time, ignore this warning.',
    'Incluya las estaciones en turnos en Diseño → Turnos de operación (la agrupación automática también las distribuye) o, si deben funcionar siempre, ignore este aviso.',
  ),
  'adv.vih_pressure_deficit.why': (
    'O aspersor mais desfavorecido da estação recebe menos que a pressão nominal: a fonte não tem pressão para vencer a perda na linha principal e o desnível até ele.',
    'The worst-placed head of the station gets less than its nominal pressure: the supply does not have the pressure to overcome the mainline loss and the rise to it.',
    'El aspersor más desfavorecido de la estación recibe menos que su presión nominal: la fuente no tiene presión para vencer la pérdida en la línea principal y el desnivel hasta él.',
  ),
  'adv.vih_pressure_deficit.how': (
    'Coloque ou troque a bomba (a correção escolhe uma para a vazão e a pressão), use tubos maiores na linha principal ou divida as estações em mais turnos. Se a pressão da fonte foi só um palpite, deixe o programa calculá-la.',
    'Add or change the pump (the correction picks one for the flow and the pressure), use larger mainline pipes or spread the stations over more flows. If the supply pressure was only a guess, let the program calculate it.',
    'Coloque o cambie la bomba (la corrección elige una para el caudal y la presión), use tuberías mayores en la línea principal o reparta las estaciones en más turnos. Si la presión de la fuente era solo una estimación, deje que el programa la calcule.',
  ),
  'adv.vih_pressure_high.why': (
    'Com a pressão que o turno precisa no aspersor mais desfavorecido, os aspersores mais baixos ou mais perto da fonte passam do máximo da faixa do bocal: molham demais e pulverizam.',
    'With the pressure the flow needs at its worst-placed head, the heads lower down or nearer the supply go beyond the top of the nozzle\'s window: they apply too much and mist.',
    'Con la presión que el turno necesita en el aspersor más desfavorecido, los aspersores más bajos o más cerca de la fuente superan el máximo del rango de la boquilla: riegan de más y pulverizan.',
  ),
  'adv.vih_pressure_high.how': (
    'Separe em turnos diferentes as estações de cotas muito diferentes, use aspersores com regulador de pressão ou uma válvula redutora no ramal das estações mais baixas.',
    'Put stations at very different elevations in different flows, use heads with a pressure regulator or a pressure-reducing valve on the branch of the lower stations.',
    'Separe en turnos distintos las estaciones de cotas muy diferentes, use aspersores con regulador de presión o una válvula reductora en el ramal de las estaciones más bajas.',
  ),
