  'veg.smoothing': ('Suavização (passadas)', 'Smoothing (passes)', 'Suavizado (pasadas)'),
  'veg.advancedHint': (
    'A limpeza dá a cada pixel a classe da maioria em volta: apaga manchas e faixas mais estreitas que o raio e fecha falhas do mesmo tamanho, sem deslocar as bordas; a das copas faz o mesmo na separação entre árvores e gramado. A suavização tira a escada dos pixels antes da simplificação, sem encolher a área.',
    'The clean-up gives every pixel the class of most of its neighbours: it erases specks and strips narrower than the radius and closes gaps as narrow, without moving the edges; the canopy clean-up does the same to the split between trees and lawn. The smoothing takes the pixel staircase off before the simplification, without shrinking the area.',
    'La limpieza da a cada píxel la clase de la mayoría a su alrededor: borra manchas y franjas más estrechas que el radio y cierra huecos del mismo tamaño, sin desplazar los bordes; la de las copas hace lo mismo en la separación entre árboles y césped. El suavizado quita la escalera de los píxeles antes de la simplificación, sin encoger el área.',
  ),
