  'ai.intro': (
    'Pergunte sobre o projeto aberto ou peça ao assistente para fazer coisas nele: distribuir aspersores, dividir um talhão em setores, dimensionar a rede, resolver as mensagens do projeto, escolher a bomba, escrever o memorial. Ele lê o projeto com as ferramentas e o motor do próprio programa; as alterações pedem sua aprovação (Configurações) e as de cada resposta podem ser desfeitas com um clique. Nada é enviado antes de você clicar em Enviar.',
    'Ask about the open project or ask the assistant to do things in it: lay out sprinklers, divide a field into blocks, size the network, fix the design messages, choose a pump, write the project report. It reads the project with the program\'s own tools and engine; changes need your approval (Settings) and the changes of each answer can be undone in one click. Nothing is sent before you press Send.',
    'Pregunte sobre el proyecto abierto o pida al asistente que haga cosas en él: distribuir aspersores, dividir un campo en sectores, dimensionar la red, resolver los mensajes del diseño, elegir la bomba, redactar la memoria. Lee el proyecto con las herramientas y el motor del propio programa; los cambios piden su aprobación (Configuración) y los de cada respuesta se deshacen con un clic. No se envía nada antes de pulsar Enviar.',
  ),
