  'ai.start.title': ('Projetar com o assistente de IA?', 'Design with the AI assistant?', '¿Diseñar con el asistente de IA?'),
  'ai.start.body': (
    'O assistente de IA pode fazer o projeto com você. Descreva a área, o que vai irrigar e de onde vem a água: ele encontra o terreno no mapa, distribui aspersores ou gotejadores, traça a rede, dimensiona tudo e explica o resultado. Você aprova cada alteração e pode desfazer qualquer uma.',
    'The AI assistant can do the design with you. Describe the area, what you will irrigate and where the water comes from: it finds the site on the map, lays out sprinklers or drippers, routes the network, sizes everything and explains the result. You approve every change and can undo any of them.',
    'El asistente de IA puede hacer el diseño con usted. Describa el área, lo que va a regar y de dónde viene el agua: encuentra el terreno en el mapa, distribuye aspersores o goteros, traza la red, lo dimensiona todo y explica el resultado. Usted aprueba cada cambio y puede deshacer cualquiera.',
  ),
  'ai.start.describe': ('Descreva o projeto (opcional)', 'Describe the project (optional)', 'Describa el proyecto (opcional)'),
