    'É preciso uma chave de API da Anthropic (Claude) ou da OpenAI (GPT): o painel do assistente mostra onde obter. O provedor cobra o uso na sua conta, e nada é enviado antes de você clicar em Enviar.',
    'You need an API key from Anthropic (Claude) or OpenAI (GPT): the assistant panel shows where to get one. The provider bills the use to your account, and nothing is sent before you press Send.',
    'Necesita una clave de API de Anthropic (Claude) o de OpenAI (GPT): el panel del asistente indica dónde obtenerla. El proveedor factura el uso en su cuenta, y no se envía nada antes de pulsar Enviar.',
