  'ai.start.never': ('Não mostrar esta tela ao iniciar', 'Don\'t show this screen at start-up', 'No mostrar esta pantalla al iniciar'),
  'ai.start.yes': ('Projetar com a IA', 'Design with AI', 'Diseñar con IA'),
  'ai.start.prompt': (
    'Quero projetar um sistema de irrigação novo. Pergunte o que você precisa saber (o local, o que vou irrigar, a fonte de água) e depois desenhe e dimensione o projeto comigo.',
