  'ai.voice.notice': (
    'O ditado usa o serviço de voz do navegador: o som da sua voz vai para os servidores dele, que o transformam em texto (o Chrome usa os do Google, o Edge os da Microsoft e o Safari os da Apple). O app não grava nem guarda o áudio, e o navegador pede permissão antes de usar o microfone. O texto ditado entra na caixa de mensagem e só vai para o assistente quando você clicar em Enviar.',
    'Dictation uses the browser\'s speech service: the sound of your voice goes to its servers, which turn it into text (Chrome uses Google\'s, Edge Microsoft\'s and Safari Apple\'s). The app neither records nor keeps the audio, and the browser asks before it uses the microphone. The dictated text goes into the message box and reaches the assistant only when you press Send.',
    'El dictado usa el servicio de voz del navegador: el sonido de su voz va a sus servidores, que lo convierten en texto (Chrome usa los de Google, Edge los de Microsoft y Safari los de Apple). La aplicación no graba ni guarda el audio, y el navegador pide permiso antes de usar el micrófono. El texto dictado entra en el cuadro del mensaje y solo llega al asistente cuando usted pulsa Enviar.',
