  'ai.err.http': ('Resposta inesperada da API da {p} (HTTP {s}): {m}', 'Unexpected response from the {p} API (HTTP {s}): {m}', 'Respuesta inesperada de la API de {p} (HTTP {s}): {m}'),
  'ai.err.unexpected': ('Erro inesperado ({e}).', 'Unexpected error ({e}).', 'Error inesperado ({e}).'),
  'ai.privacy': (
    'O que é enviado: quando você envia uma mensagem, ela, os arquivos anexados, os dados do projeto marcados abaixo (com a primeira mensagem, ou quando você marcar de novo), as notas de IA do projeto, as mensagens anteriores desta conversa e as instruções do programa vão por HTTPS à API da {p} ({h}) com a sua chave da {p}, para o modelo escolhido ({m}), e são processados nos termos da sua conta na {p}. Enquanto trabalha, o assistente lê mais do projeto com as ferramentas (inclusive imagens do desenho e do mapa base); esses resultados também são enviados. Ferramentas que consultam outros serviços (busca de endereço no OpenStreetMap, relevo, clima, catálogos) mandam a eles só o necessário e pedem sua aprovação, salvo no modo automático. Nada é enviado antes de você enviar. Cada chave vai só à API da sua empresa e fica na memória durante a sessão, a menos que você marque “Lembrar a chave neste dispositivo”.',
    'What is sent: when you send a message, it, the files you attached, the project data ticked below (with the first message, or when you tick it again), the project\'s AI notes, the earlier messages of this conversation and the program\'s instructions go over HTTPS to the {p} API ({h}) with your {p} key, for the chosen model ({m}), and are processed under your {p} account\'s terms. While working, the assistant reads more of the project with its tools (pictures of the drawing and base map included); those results are sent too. Tools that ask other services (address search on OpenStreetMap, terrain, climate, catalogues) send them only what they need and ask for your approval, except in automatic mode. Nothing is sent before you send. Each key goes only to its own company\'s API and stays in memory for the session unless you tick “Remember the key on this device”.',
    'Qué se envía: cuando usted envía un mensaje, este, los archivos adjuntos, los datos del proyecto marcados abajo (con el primer mensaje, o cuando vuelva a marcarlos), las notas de IA del proyecto, los mensajes anteriores de esta conversación y las instrucciones del programa van por HTTPS a la API de {p} ({h}) con su clave de {p}, para el modelo elegido ({m}), y se procesan según los términos de su cuenta de {p}. Mientras trabaja, el asistente lee más del proyecto con sus herramientas (incluidas imágenes del dibujo y del mapa base); esos resultados también se envían. Las herramientas que consultan otros servicios (búsqueda de direcciones en OpenStreetMap, relieve, clima, catálogos) les envían solo lo necesario y piden su aprobación, salvo en el modo automático. No se envía nada antes de que usted lo envíe. Cada clave va solo a la API de su empresa y queda en memoria durante la sesión, salvo que marque “Recordar la clave en este dispositivo”.',
  ),
