    'Review this design without changing anything: look at it in pictures (the zones, the problems marked, pressures and velocities over the drawing), read the messages and the report tables, and give me a checklist, most important first: each point OK, attention or problem, with its figures and where to fix it. {x}',
    'Revise este diseño sin cambiar nada: mírelo en imágenes (las zonas, los problemas marcados, presiones y velocidades sobre el dibujo), lea los mensajes y las tablas de informes y deme una lista de verificación, de lo más importante a lo menos: cada punto OK, atención o problema, con sus cifras y dónde corregirlo. {x}',
