  'ai.do.import': ('Importar {n}', 'Import {n}', 'Importar {n}'),
  'hist.aiNotes': ('Notas da IA', 'AI notes', 'Notas de la IA'),
  'about.text': (
    'OpenCADIrrigation — CAD gratuito e de código aberto para projeto de irrigação pressurizada: gotejamento, microaspersão, aspersão, paisagismo, campos esportivos, pivôs e lineares.\nMotor hidráulico próprio: Hazen‑Williams, Darcy‑Weisbach, Scobey e Manning; rede pelo Global Gradient Algorithm (Todini‑Pilati); dimensionamento por programação linear com as classes de pressão; transientes pelo método das características; simulação de 24 horas. Calcula projetos grandes em segundos.\nProjeto automático, agronomia, máquinas, orçamento e pranchas; DXF/DWG, PDF, KML, SHP, GeoJSON e EPANET. O desenho continua fluido mesmo com dezenas de milhares de itens e centenas de camadas.\nAssistente de IA opcional (Anthropic ou OpenAI, com a sua própria chave) que encontra o terreno, desenha, dimensiona e explica o projeto com você; cada alteração pode ser aprovada e desfeita.\nO assistente vê o desenho sobre a imagem de satélite, contorna os talhões sozinho, revisa o projeto e confere a prancha antes de imprimir; você pode marcar pontos no mapa para ele, ditar por voz e enviar fotos de campo com GPS, e a conversa continua se a página recarregar.\nAo abrir, pergunta onde fica a área (endereço ou coordenadas) e se você quer projetar com a IA.\nRoda no navegador, também sem rede, sem cadastro e sem servidor, em 20 idiomas.',
    'OpenCADIrrigation — free and open-source CAD for pressurised irrigation design: drip, micro-sprinklers, sprinklers, landscape, sports fields, centre pivots and linear moves.\nIts own hydraulic engine: Hazen‑Williams, Darcy‑Weisbach, Scobey and Manning; networks by the Global Gradient Algorithm (Todini‑Pilati); linear-programming sizing within the pressure classes; transients by the method of characteristics; 24-hour simulation. It calculates large designs in seconds.\nAutomatic design, agronomy, machines, quotes and drawing sheets; DXF/DWG, PDF, KML, SHP, GeoJSON and EPANET. The drawing stays fluid even with tens of thousands of items and hundreds of layers.\nAn optional AI assistant (Anthropic or OpenAI, with your own key) that finds the site, draws, sizes and explains the design with you; every change can be approved and undone.\nThe assistant sees the drawing over the satellite image, outlines the fields by itself, reviews the design and checks the sheet before printing; you can mark places on the map for it, dictate by voice and send field photos with GPS, and the conversation is kept if the page reloads.\nOn opening it asks where the area is (an address or coordinates) and whether you want to design with the AI.\nRuns in the browser, also offline, with no sign-up and no server, in 20 languages.',
    'OpenCADIrrigation — CAD gratuito y de código abierto para el diseño de riego presurizado: goteo, microaspersión, aspersión, paisajismo, campos deportivos, pívots y laterales de avance.\nMotor hidráulico propio: Hazen‑Williams, Darcy‑Weisbach, Scobey y Manning; red por el Global Gradient Algorithm (Todini‑Pilati); dimensionamiento por programación lineal dentro de las clases de presión; transitorios por el método de las características; simulación de 24 horas. Calcula proyectos grandes en segundos.\nDiseño automático, agronomía, máquinas, presupuesto y planos; DXF/DWG, PDF, KML, SHP, GeoJSON y EPANET. El dibujo sigue fluido incluso con decenas de miles de elementos y cientos de capas.\nAsistente de IA opcional (Anthropic u OpenAI, con su propia clave) que encuentra el terreno, dibuja, dimensiona y explica el diseño con usted; cada cambio se puede aprobar y deshacer.\nEl asistente ve el dibujo sobre la imagen satelital, contornea las parcelas por sí solo, revisa el diseño y comprueba la lámina antes de imprimir; puede marcarle puntos en el mapa, dictar por voz y enviar fotos de campo con GPS, y la conversación se conserva si la página se recarga.\nAl abrirse, pregunta dónde está el área (dirección o coordenadas) y si quiere diseñar con la IA.\nFunciona en el navegador, también sin red, sin registro y sin servidor, en 20 idiomas.',
  ),
  'about.credits': (
    'Dados de terceiros: mapas © colaboradores do OpenStreetMap (ODbL); imagens de satélite Esri World Imagery; relevo Terrain Tiles (AWS Open Data); clima Open-Meteo e NASA POWER; fontes Noto (SIL Open Font License 1.1). Os catálogos de fabricantes vêm das tabelas publicadas por eles. Busca de endereços: Nominatim, com dados © colaboradores do OpenStreetMap.',
    'Third-party data: maps © OpenStreetMap contributors (ODbL); satellite imagery Esri World Imagery; terrain Terrain Tiles (AWS Open Data); climate Open-Meteo and NASA POWER; Noto fonts (SIL Open Font License 1.1). Manufacturer catalogues come from the tables they publish. Address search: Nominatim, with data © OpenStreetMap contributors.',
    'Datos de terceros: mapas © colaboradores de OpenStreetMap (ODbL); imágenes satelitales Esri World Imagery; relieve Terrain Tiles (AWS Open Data); clima Open-Meteo y NASA POWER; fuentes Noto (SIL Open Font License 1.1). Los catálogos de fabricantes provienen de las tablas que ellos publican. Búsqueda de direcciones: Nominatim, con datos © colaboradores de OpenStreetMap.',
  ),
